    e=os.environ.copy(); e.update({"GIT_AUTHOR_NAME":"Alice","GIT_AUTHOR_EMAIL":"alice@example.com","GIT_COMMITTER_NAME":"Alice","GIT_COMMITTER_EMAIL":"alice@example.com","GIT_AUTHOR_DATE":date,"GIT_COMMITTER_DATE":date})
