import pty, os, subprocess, fcntl, termios, struct, sys
EXE="/workspace/executable"
def run_pty(args,cwd,cols,rows=24):
    # use subprocess with pty via script? Use python pty fork
    pid, fd = pty.fork()
    if pid==0:
        os.chdir(cwd)
        os.execv(EXE,[EXE]+args)
    else:
        fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack("HHHH", rows, cols, 0,0))
        out=b""
        while True:
            try:
                data=os.read(fd, 4096)
                if not data: break
                out+=data
            except OSError:
                break
        _,status=os.waitpid(pid,0)
        return out.decode(), os.waitstatus_to_exitcode(status)
for cols in [20,40,80,0]:
    out,rc=run_pty([],"/tmp/wrap1",cols)
    print("cols",cols,"rc",rc,repr(out))
# also many commits pager check
PY"}

