use chrono::{DateTime, FixedOffset, TimeZone, Utc};
use clap::{Arg, ArgAction, Command};
use git2::{BranchType, Oid, Repository, Sort};
use regex::Regex;
use serde::{Deserialize, Serialize};
use std::collections::{HashMap, HashSet};
use std::fs;
use std::io::IsTerminal;
use std::path::PathBuf;
use std::process::ExitCode;
use std::time::Instant;
use unicode_width::UnicodeWidthChar;

const GIT_FLOW_TOML: &str = include_str!("models/git-flow.toml");
const SIMPLE_TOML: &str = include_str!("models/simple.toml");
const NONE_TOML: &str = include_str!("models/none.toml");

#[derive(Debug)]
enum AppError {
    Msg(String),
    Io(std::io::Error),
    Toml(toml::de::Error),
    Git(git2::Error),
    Regex(regex::Error),
}
impl std::fmt::Display for AppError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            AppError::Msg(s) => write!(f, "{}", s),
            AppError::Io(e) => write!(f, "{}", e),
            AppError::Toml(e) => write!(f, "{}", e),
            AppError::Git(e) => write!(f, "{}", e.message()),
            AppError::Regex(e) => write!(f, "{}", e),
        }
    }
}
impl From<std::io::Error> for AppError { fn from(e: std::io::Error) -> Self { AppError::Io(e) } }
impl From<toml::de::Error> for AppError { fn from(e: toml::de::Error) -> Self { AppError::Toml(e) } }
impl From<git2::Error> for AppError { fn from(e: git2::Error) -> Self { AppError::Git(e) } }
impl From<regex::Error> for AppError { fn from(e: regex::Error) -> Self { AppError::Regex(e) } }
fn msg_err(s: String) -> AppError { AppError::Msg(s) }

fn main() -> ExitCode {
    if let Err(e) = ensure_model_files() {
        eprintln!("{}", e);
        return ExitCode::from(1);
    }
    let matches = build_cli().get_matches();
    match run(&matches) {
        Ok(()) => ExitCode::from(0),
        Err(e) => {
            eprintln!("{}", e);
            ExitCode::from(1)
        }
    }
}

fn build_cli() -> Command {
    let intro = "Structured Git graphs for your branching model.\n    https://github.com/mlange-42/git-graph\n\nEXAMPES:\n    git-graph                   -> Show graph\n    git-graph --style round     -> Show graph in a different style\n    git-graph --model <model>   -> Show graph using a certain <model>\n    git-graph model --list      -> List available branching models\n    git-graph model             -> Show repo's current branching models\n    git-graph model <model>     -> Permanently set model <model> for this repo";
    Command::new("git-graph")
        .version("0.7.0")
        .about(intro)
        .arg(Arg::new("path").short('p').long("path").value_name("path")
            .help("Open repository from this path or above. Default '.'")
            .num_args(1))
        .arg(Arg::new("skip-repo-owner-validation").long("skip-repo-owner-validation").action(ArgAction::SetTrue)
            .help("Skip owner validation for the repository.\nThis will turn off libgit2's owner validation, which may increase security risks.\nPlease do not disable this validation for repositories you do not trust."))
        .arg(Arg::new("model").short('m').long("model").value_name("model")
            .help("Branching model. Available presets are [simple|git-flow|none].\nDefault: git-flow. \nPermanently set the model for a repository with\n> git-graph model <model>")
            .num_args(1))
        .arg(Arg::new("max-count").short('n').long("max-count").value_name("n")
            .help("Maximum number of commits").num_args(1))
        .arg(Arg::new("color").long("color").value_name("color")
            .help("Specify when colors should be used. One of [auto|always|never].\nDefault: auto.").num_args(1))
        .arg(Arg::new("no-color").long("no-color").action(ArgAction::SetTrue)
            .help("Print without colors. Missing color support should be detected\nautomatically (e.g. when piping to a file).\nOverrides option '--color'"))
        .arg(Arg::new("wrap").short('w').long("wrap").value_name("wrap").num_args(0..=3)
            .help("Line wrapping for formatted commit text. Default: 'auto 0 8'\nArgument format: [<width>|auto|none[ <indent1>[ <indent2>]]]\nFor examples, consult 'git-graph --help'")
            .long_help("Line wrapping for formatted commit text. Default: 'auto 0 8'\nArgument format: [<width>|auto|none[ <indent1>[ <indent2>]]]\nExamples:\n    git-graph --wrap auto\n    git-graph --wrap auto 0 8\n    git-graph --wrap none\n    git-graph --wrap 80\n    git-graph --wrap 80 0 8\n'auto' uses the terminal's width if on a terminal."))
        .arg(Arg::new("format").short('f').long("format").value_name("format")
            .help("Commit format. One of [oneline|short|medium|full|\"<string>\"].\n  (First character can be used as abbreviation, e.g. '-f m')\nDefault: oneline.\nFor placeholders supported in \"<string>\", consult 'git-graph --help'")
            .long_help("Commit format. One of [oneline|short|medium|full|\"<string>\"].\n  (First character can be used as abbreviation, e.g. '-f m')\nFormatting placeholders for \"<string>\":\n    %n    newline\n    %H    commit hash\n    %h    abbreviated commit hash\n    %P    parent commit hashes\n    %p    abbreviated parent commit hashes\n    %d    refs (branches, tags)\n    %s    commit summary\n    %b    commit message body\n    %B    raw body (subject and body)\n    %an   author name\n    %ae   author email\n    %ad   author date\n    %as   author date in short format 'YYYY-MM-DD'\n    %cn   committer name\n    %ce   committer email\n    %cd   committer date\n    %cs   committer date in short format 'YYYY-MM-DD'\n    \n    If you add a + (plus sign) after % of a placeholder,\n       a line-feed is inserted immediately before the expansion if\n       and only if the placeholder expands to a non-empty string.\n    If you add a - (minus sign) after % of a placeholder, all\n       consecutive line-feeds immediately preceding the expansion are\n       deleted if and only if the placeholder expands to an empty string.\n    If you add a ' ' (space) after % of a placeholder, a space is\n       inserted immediately before the expansion if and only if\n       the placeholder expands to a non-empty string.\n\n    See also the respective git help: https://git-scm.com/docs/pretty-formats\n")
            .num_args(1))
        .arg(Arg::new("reverse").short('r').long("reverse").action(ArgAction::SetTrue).help("Reverse the order of commits."))
        .arg(Arg::new("local").short('l').long("local").action(ArgAction::SetTrue).help("Show only local branches, no remotes."))
        .arg(Arg::new("svg").long("svg").action(ArgAction::SetTrue).help("Render graph as SVG instead of text-based."))
        .arg(Arg::new("debug").short('d').long("debug").action(ArgAction::SetTrue).help("Additional debug output and graphics."))
        .arg(Arg::new("sparse").short('S').long("sparse").action(ArgAction::SetTrue).help("Print a less compact graph: merge lines point to target lines\nrather than merge commits."))
        .arg(Arg::new("style").short('s').long("style").value_name("style")
            .help("Output style. One of [normal/thin|round|bold|double|ascii].\n  (First character can be used as abbreviation, e.g. '-s r')").num_args(1))
        .subcommand(Command::new("model").about("Prints or permanently sets the branching model for a repository.")
            .arg(Arg::new("model").value_name("model")
                .help("The branching model to be used. Available presets are [simple|git-flow|none].\nWhen not given, prints the currently set model."))
            .arg(Arg::new("list").short('l').long("list").action(ArgAction::SetTrue).help("List all available branching models.")))
}

fn config_dir() -> PathBuf {
    dirs::config_dir().unwrap_or_default()
}
fn models_dir() -> PathBuf {
    config_dir().join("git-graph").join("models")
}
fn ensure_model_files() -> Result<(), AppError> {
    let dir = models_dir();
    if !dir.exists() {
        fs::create_dir_all(&dir)?;
        fs::write(dir.join("git-flow.toml"), GIT_FLOW_TOML)?;
        fs::write(dir.join("simple.toml"), SIMPLE_TOML)?;
        fs::write(dir.join("none.toml"), NONE_TOML)?;
    }
    Ok(())
}
fn available_models() -> Result<Vec<String>, AppError> {
    let dir = models_dir();
    let mut result = Vec::new();
    for entry in fs::read_dir(&dir)? {
        let path = entry?.path();
        if path.extension().map(|e| e == "toml").unwrap_or(false) {
            if let Some(stem) = path.file_stem().and_then(|s| s.to_str()) {
                result.push(stem.to_string());
            }
        }
    }
    Ok(result)
}

#[derive(Deserialize, Serialize)]
struct RepoSettings { model: String }

fn open_repo(path_str: &str) -> Result<Repository, AppError> {
    Repository::discover(path_str).map_err(|e| {
        msg_err(format!("ERROR: {}\n       Navigate into a repository before running git-graph, or use option --path", e.message()))
    })
}
fn repo_settings_path(repo: &Repository) -> PathBuf {
    repo.path().join("git-graph.toml")
}
fn read_repo_settings(repo: &Repository) -> Result<Option<RepoSettings>, AppError> {
    let path = repo_settings_path(repo);
    if path.exists() {
        let text = fs::read_to_string(&path)?;
        let parsed: RepoSettings = toml::from_str(&text)?;
        Ok(Some(parsed))
    } else { Ok(None) }
}

#[derive(Deserialize)]
struct ModelFile {
    persistence: Vec<String>,
    order: Vec<String>,
    terminal_colors: ColorSettingsFile,
    svg_colors: ColorSettingsFile,
}
#[derive(Deserialize)]
struct ColorSettingsFile {
    matches: Vec<(String, Vec<String>)>,
    unknown: Vec<String>,
}
struct CompiledModel {
    persistence: Vec<Regex>,
    order: Vec<Regex>,
    terminal_matches: Vec<(Regex, Vec<String>)>,
    svg_matches: Vec<(Regex, Vec<String>)>,
    terminal_unknown: Vec<String>,
    svg_unknown: Vec<String>,
}
impl CompiledModel {
    fn compile(m: ModelFile) -> Result<Self, AppError> {
        let mut persistence = Vec::new();
        for p in &m.persistence { persistence.push(Regex::new(p)?); }
        let mut order = Vec::new();
        for p in &m.order { order.push(Regex::new(p)?); }
        let mut terminal_matches = Vec::new();
        for (p, cols) in &m.terminal_colors.matches { terminal_matches.push((Regex::new(p)?, cols.clone())); }
        let mut svg_matches = Vec::new();
        for (p, cols) in &m.svg_colors.matches { svg_matches.push((Regex::new(p)?, cols.clone())); }
        // validate terminal colors after all regexes
        for (_, cols) in &terminal_matches { for c in cols { parse_terminal_color(c)?; } }
        for c in &m.terminal_colors.unknown { parse_terminal_color(c)?; }
        Ok(CompiledModel { persistence, order, terminal_matches, svg_matches, terminal_unknown: m.terminal_colors.unknown, svg_unknown: m.svg_colors.unknown })
    }
    fn persistence_of(&self, name: &str) -> usize {
        for (i, re) in self.persistence.iter().enumerate() { if re.is_match(name) { return i; } }
        self.persistence.len()
    }
    fn order_of(&self, name: &str) -> usize {
        for (i, re) in self.order.iter().enumerate() { if re.is_match(name) { return i; } }
        self.order.len()
    }
    fn terminal_list<'a>(&'a self, name: &str) -> &'a Vec<String> {
        for (re, cols) in &self.terminal_matches { if re.is_match(name) { return cols; } }
        &self.terminal_unknown
    }
    fn svg_list<'a>(&'a self, name: &str) -> &'a Vec<String> {
        for (re, cols) in &self.svg_matches { if re.is_match(name) { return cols; } }
        &self.svg_unknown
    }
}
fn parse_terminal_color(s: &str) -> Result<u8, AppError> {
    let v = match s {
        "black" => 0, "red" => 1, "green" => 2, "yellow" => 3, "blue" => 4, "magenta" => 5, "cyan" => 6, "white" => 7,
        "bright_black" => 8, "bright_red" => 9, "bright_green" => 10, "bright_yellow" => 11, "bright_blue" => 12,
        "bright_magenta" => 13, "bright_cyan" => 14, "bright_white" => 15,
        _ => {
            if let Ok(n) = s.parse::<u8>() { n } else { return Err(msg_err(format!("Color {} not found", s))); }
        }
    };
    Ok(v)
}
fn get_model(name: &str) -> Result<CompiledModel, AppError> {
    let dir = models_dir();
    let path = dir.join(format!("{}.toml", name));
    if !path.exists() {
        let available = available_models()?;
        return Err(msg_err(format!("ERROR: No branching model named '{}' found in {}\n       Available models are: {}", name, dir.display(), available.join(", "))));
    }
    let text = fs::read_to_string(&path)?;
    let parsed: ModelFile = toml::from_str(&text)?;
    CompiledModel::compile(parsed)
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum ColorMode { Auto, Always, Never }
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Style { Thin, Round, Bold, Double, Ascii }
#[derive(Clone, Debug)]
struct WrapConfig { width: Option<usize>, indent1: usize, indent2: usize }

struct Settings {
    model: CompiledModel,
    max_count: Option<usize>,
    use_color: bool,
    style: Style,
    format: String,
    wrap: WrapConfig,
    reverse: bool,
    local: bool,
    svg: bool,
    debug: bool,
    sparse: bool,
}

fn terminal_width() -> Option<usize> {
    unsafe {
        let mut ws: libc::winsize = std::mem::zeroed();
        if libc::ioctl(libc::STDOUT_FILENO, libc::TIOCGWINSZ, &mut ws) == 0 && ws.ws_col > 0 {
            Some(ws.ws_col as usize)
        } else { None }
    }
}
fn parse_wrap(values: Option<Vec<String>>) -> Result<WrapConfig, AppError> {
    let default_vec = vec!["auto".to_string(), "0".to_string(), "8".to_string()];
    let vals = match values {
        None => default_vec,
        Some(v) if v.is_empty() => default_vec,
        Some(v) => v,
    };
    let joined = vals.join(" ");
    if joined.starts_with("none") {
        return Ok(WrapConfig { width: None, indent1: 0, indent2: 0 });
    }
    // parse
    let mut width: Option<usize> = None;
    let mut indent1 = 0usize;
    let mut indent2 = 0usize;
    let parse_err = || msg_err(format!("ERROR: Can't parse option --wrap '{}' to integers.", joined));
    if joined.starts_with("auto") {
        // replace auto with terminal width, or a very large value when not a terminal
        let w_str = match terminal_width() {
            Some(w) => {
                if std::io::stdout().is_terminal() {
                    if w <= 44 { "999999".to_string() } else { format!("{}", w.saturating_sub(4)) }
                } else { "999999".to_string() }
            }
            None => "999999".to_string(),
        };
        let replaced = format!("{}{}", w_str, &joined[4..]);
        let parts: Vec<&str> = replaced.split_whitespace().collect();
        let mut nums = Vec::new();
        for p in &parts { nums.push(p.parse::<usize>().map_err(|_| parse_err())?); }
        if nums.is_empty() { return Err(parse_err()); }
        width = Some(nums[0]);
        if nums.len() > 1 { indent1 = nums[1]; }
        if nums.len() > 2 { indent2 = nums[2]; }
    } else {
        let parts: Vec<&str> = joined.split_whitespace().collect();
        let mut nums = Vec::new();
        for p in &parts { nums.push(p.parse::<usize>().map_err(|_| parse_err())?); }
        if nums.is_empty() { return Err(parse_err()); }
        width = Some(nums[0]);
        if nums.len() > 1 { indent1 = nums[1]; }
        if nums.len() > 2 { indent2 = nums[2]; }
    }
    Ok(WrapConfig { width, indent1, indent2 })
}

fn run(matches: &clap::ArgMatches) -> Result<(), AppError> {
    if matches.get_flag("skip-repo-owner-validation") {
        let _ = git2::opts::set_verify_owner(false);
    }
    let path_str = matches.get_one::<String>("path").cloned().unwrap_or_else(|| ".".to_string());

    if let Some(sub) = matches.subcommand_matches("model") {
        if sub.get_flag("list") {
            let models = available_models()?;
            println!("{}", models.join("\n"));
            return Ok(());
        }
        let repo = open_repo(&path_str)?;
        if let Some(model_name) = sub.get_one::<String>("model") {
            let available = available_models()?;
            if !available.iter().any(|m| m == model_name) {
                let dir = models_dir();
                return Err(msg_err(format!("ERROR: No branching model named '{}' found in {}\n       Available models are: {}", model_name, dir.display(), available.join(", "))));
            }
            let settings = RepoSettings { model: model_name.clone() };
            let text = toml::to_string(&settings).map_err(|e| msg_err(e.to_string()))?;
            fs::write(repo_settings_path(&repo), text)?;
            eprint!("Branching model set to '{}'", model_name);
            return Ok(());
        } else {
            match read_repo_settings(&repo)? {
                Some(s) => { print!("{}", s.model); }
                None => { print!("No branching model set"); }
            }
            return Ok(());
        }
    }

    // Main graph flow
    let repo = open_repo(&path_str)?;

    // max-count
    let max_count: Option<usize> = match matches.get_one::<String>("max-count") {
        Some(s) => {
            match s.parse::<usize>() {
                Ok(v) => Some(v),
                Err(_) => return Err(msg_err(format!("Option max-count must be a positive number, but got '{}'", s))),
            }
        }
        None => None,
    };
    // style
    let style_str = matches.get_one::<String>("style").cloned().unwrap_or_else(|| "thin".to_string());
    let style = match style_str.as_str() {
        "normal" | "thin" | "n" | "t" => Style::Thin,
        "round" | "r" => Style::Round,
        "bold" | "b" => Style::Bold,
        "double" | "d" => Style::Double,
        "ascii" | "a" => Style::Ascii,
        _ => return Err(msg_err(format!("Unknown characters/style '{}'. Must be one of [normal|thin|round|bold|double|ascii]", style_str))),
    };
    // model
    let model_name: String = if let Some(m) = matches.get_one::<String>("model") {
        m.clone()
    } else if let Some(repo_settings) = read_repo_settings(&repo)? {
        repo_settings.model
    } else {
        "git-flow".to_string()
    };
    let compiled_model = get_model(&model_name)?;

    // color
    let use_color = if matches.get_flag("no-color") {
        false
    } else {
        let color_str = matches.get_one::<String>("color").cloned().unwrap_or_else(|| "auto".to_string());
        match color_str.as_str() {
            "always" => true,
            "never" => false,
            "auto" => std::io::stdout().is_terminal(),
            _ => return Err(msg_err(format!("Unknown color mode '{}'. Supports [auto|always|never].", color_str))),
        }
    };
    // wrap
    let wrap_vals: Option<Vec<String>> = matches.get_many::<String>("wrap").map(|v| v.cloned().collect());
    let wrap = parse_wrap(wrap_vals)?;

    let settings = Settings {
        model: compiled_model,
        max_count,
        use_color,
        style,
        format: matches.get_one::<String>("format").cloned().unwrap_or_else(|| "oneline".to_string()),
        wrap,
        reverse: matches.get_flag("reverse"),
        local: matches.get_flag("local"),
        svg: matches.get_flag("svg"),
        debug: matches.get_flag("debug"),
        sparse: matches.get_flag("sparse"),
    };

    let start = Instant::now();
    let graph = GitGraph::new(&repo, &settings)?;
    let construction_ms = start.elapsed().as_secs_f64() * 1000.0;
    if settings.debug {
        for branch in &graph.branches {
            let marker = if branch.merge_created { "m" } else { "" };
            eprintln!("{} (col {}) ({:?}) {} s: {:?}, t: {:?}", branch.name, branch.column.unwrap_or(99), branch.range, marker, branch.source_group, branch.target_group);
        }
    }
    let print_start = Instant::now();
    let output = if settings.svg {
        render_svg(&graph, &settings)
    } else {
        render_text(&graph, &settings)
    };
    print!("{}", output);
    let printing_ms = print_start.elapsed().as_secs_f64() * 1000.0;
    if settings.debug {
        eprintln!("Graph construction: {:.1} ms, printing: {:.1} ms ({} commits)", construction_ms, printing_ms, graph.commits.len());
    }
    Ok(())
}

// ---------- Graph ----------

#[derive(Clone)]
struct SigInfo { name: String, email: String, seconds: i64, offset_minutes: i32 }
#[derive(Clone)]
struct CommitData {
    oid: Oid,
    parents: Vec<Oid>,
    author: SigInfo,
    committer: SigInfo,
    summary: String,
    body: String,
    message: String,
    branch: Option<usize>,
}
#[derive(Clone, Copy, PartialEq, Eq)]
enum RefKind { Branch, Tag }
struct BranchInfo {
    name: String,
    match_name: String,
    persistence_name: String,
    head_oid: Option<Oid>,
    kind: Option<RefKind>, // None for anonymous
    merge_created: bool,
    merge_commit_idx: Option<usize>, // original index
    trace: Vec<usize>, // original indices in trace order
    range: (Option<usize>, Option<usize>),
    source_group: Option<usize>,
    target_group: Option<usize>,
    column: Option<usize>,
    term_color: u8,
    svg_color: String,
    // computed visual
    first_assign_filtered: Option<usize>,
    visual_start_filtered: Option<usize>,
    visual_end_filtered: Option<usize>,
}
struct GitGraph {
    commits: Vec<CommitData>, // filtered
    branches: Vec<BranchInfo>,
    head_branch: Option<String>,
    head_oid: Option<Oid>,
    head_is_branch: bool,
    max_column: usize,
}

impl GitGraph {
    fn new(repo: &Repository, settings: &Settings) -> Result<Self, AppError> {
        // HEAD (errors on empty repo)
        let head_ref = repo.head()?;
        let head_is_branch = head_ref.is_branch();
        let head_branch = if head_is_branch { head_ref.shorthand().map(|s| s.to_string()) } else { None };
        let head_oid = head_ref.target();

        // named branches
        #[derive(Clone)]
        struct NamedRef { name: String, match_name: String, head: Oid, kind: RefKind }
        let mut named: Vec<NamedRef> = Vec::new();
        {
            let mut iter = repo.branches(None)?;
            while let Some(item) = iter.next() {
                let (branch, btype) = item?;
                if settings.local && btype == BranchType::Remote { continue; }
                let reference = branch.get();
                let name_opt = reference.shorthand().map(|s| s.to_string()).or_else(|| {
                    reference.name().map(|full| {
                        let mut s = full.to_string();
                        for pre in ["refs/heads/", "refs/remotes/"] { if s.starts_with(pre) { s = s[pre.len()..].to_string(); break; } }
                        s
                    })
                });
                let name = match name_opt { Some(n) => n, None => continue };
                let target = match reference.target().or_else(|| reference.peel_to_commit().ok().map(|c| c.id())) { Some(t) => t, None => continue };
                let match_name = if btype == BranchType::Remote {
                    if let Some(stripped) = name.strip_prefix("origin/") { stripped.to_string() } else { name.clone() }
                } else { name.clone() };
                named.push(NamedRef { name, match_name, head: target, kind: RefKind::Branch });
            }
        }
        {
            if let Ok(tags) = repo.tag_names(None) {
                for i in 0..tags.len() {
                    if let Some(tag) = tags.get(i) {
                        let refname = format!("refs/tags/{}", tag);
                        if let Ok(reference) = repo.find_reference(&refname) {
                            let target = reference.peel_to_commit().map(|c| c.id()).ok().or_else(|| reference.target());
                            if let Some(t) = target {
                                let full = format!("tags/{}", tag);
                                named.push(NamedRef { name: full.clone(), match_name: full, head: t, kind: RefKind::Tag });
                            }
                        }
                    }
                }
            }
        }

        // commits via revwalk
        let mut all_commits: Vec<CommitData> = Vec::new();
        let mut index_map: HashMap<Oid, usize> = HashMap::new();
        {
            let mut walk = repo.revwalk()?;
            for n in &named { let _ = walk.push(n.head); }
            walk.set_sorting(Sort::TOPOLOGICAL | Sort::TIME)?;
            for oid_res in walk.by_ref() {
                if let Some(max) = settings.max_count { if all_commits.len() >= max { break; } }
                let oid = oid_res?;
                let commit = repo.find_commit(oid)?;
                let parents: Vec<Oid> = (0..commit.parent_count()).filter_map(|i| commit.parent_id(i).ok()).collect();
                let author = sig_info(&commit.author());
                let committer = sig_info(&commit.committer());
                let summary = String::from_utf8_lossy(commit.summary_bytes()).to_string();
                let body = String::from_utf8_lossy(commit.body_bytes().unwrap_or(b"")).to_string();
                let message = String::from_utf8_lossy(commit.message_bytes()).to_string();
                index_map.insert(oid, all_commits.len());
                all_commits.push(CommitData { oid, parents, author, committer, summary, body, message, branch: None });
            }
        }

        // build candidate branches: anonymous first, then named
        let mut branches: Vec<BranchInfo> = Vec::new();
        for (idx, c) in all_commits.iter().enumerate() {
            if c.parents.len() > 1 {
                for p in c.parents.iter().skip(1) {
                    branches.push(BranchInfo {
                        name: "unknown".to_string(), match_name: "unknown".to_string(), persistence_name: "unknown".to_string(),
                        head_oid: Some(*p), kind: None, merge_created: true, merge_commit_idx: Some(idx),
                        trace: Vec::new(), range: (None, None), source_group: None, target_group: None, column: None,
                        term_color: 7, svg_color: "gray".to_string(), first_assign_filtered: None, visual_start_filtered: None, visual_end_filtered: None,
                    });
                }
            }
        }
        for n in &named {
            branches.push(BranchInfo {
                name: n.name.clone(), match_name: n.match_name.clone(), persistence_name: n.match_name.clone(),
                head_oid: Some(n.head), kind: Some(n.kind), merge_created: false, merge_commit_idx: None,
                trace: Vec::new(), range: (None, None), source_group: None, target_group: None, column: None,
                term_color: 7, svg_color: "gray".to_string(), first_assign_filtered: None, visual_start_filtered: None, visual_end_filtered: None,
            });
        }
        // sort by persistence (stable)
        branches.sort_by_key(|b| settings.model.persistence_of(&b.persistence_name));

        // trace
        for bi in 0..branches.len() {
            let head_oid = match branches[bi].head_oid { Some(o) => o, None => continue };
            let head_idx = match index_map.get(&head_oid) { Some(i) => *i, None => continue };
            if all_commits[head_idx].branch.is_some() { continue; }
            let mut cur = head_idx;
            loop {
                if all_commits[cur].branch.is_some() { break; }
                all_commits[cur].branch = Some(bi);
                branches[bi].trace.push(cur);
                if all_commits[cur].parents.is_empty() { break; }
                let poid = all_commits[cur].parents[0];
                let pidx = match index_map.get(&poid) { Some(i) => *i, None => break };
                if all_commits[pidx].branch.is_some() { break; }
                cur = pidx;
            }
        }
        // remove anonymous branches with no trace
        let mut old_to_new: HashMap<usize, usize> = HashMap::new();
        let mut new_branches: Vec<BranchInfo> = Vec::new();
        for (old_idx, b) in branches.into_iter().enumerate() {
            if b.merge_created && b.trace.is_empty() { continue; }
            old_to_new.insert(old_idx, new_branches.len());
            new_branches.push(b);
        }
        let mut branches = new_branches;
        for c in all_commits.iter_mut() {
            if let Some(old) = c.branch { c.branch = old_to_new.get(&old).copied(); }
        }

        // filtered commits
        let mut filtered_index: HashMap<usize, usize> = HashMap::new();
        let mut filtered_commits: Vec<CommitData> = Vec::new();
        for (orig_idx, c) in all_commits.iter().enumerate() {
            if c.branch.is_some() {
                filtered_index.insert(orig_idx, filtered_commits.len());
                filtered_commits.push(c.clone());
            }
        }
        let n_filtered = filtered_commits.len();

        // resolve anonymous names
        // first need assigned branch of merge commits (filtered or original). Use original all_commits branch (already remapped)
        fn resolve_name(idx: usize, branches: &Vec<BranchInfo>, all_commits: &Vec<CommitData>, visited: &mut HashSet<usize>) -> String {
            if branches[idx].kind.is_some() { return branches[idx].name.clone(); }
            if !visited.insert(idx) { return "unknown".to_string(); }
            if let Some(mci) = branches[idx].merge_commit_idx {
                if let Some(target_branch) = all_commits[mci].branch {
                    let target_name = resolve_name(target_branch, branches, all_commits, visited);
                    if target_name == "unknown" { return "fork/unknown".to_string(); } else { return "unknown".to_string(); }
                }
            }
            "unknown".to_string()
        }
        for i in 0..branches.len() {
            if branches[i].merge_created {
                let mut vis = HashSet::new();
                let nm = resolve_name(i, &branches, &all_commits, &mut vis);
                branches[i].name = nm.clone();
                branches[i].match_name = nm;
                // persistence_name stays "unknown"
            }
        }

        // helper to get order group
        let order_groups: Vec<usize> = branches.iter().map(|b| settings.model.order_of(&b.match_name)).collect();

        // ranges, source, target
        for bi in 0..branches.len() {
            if branches[bi].trace.is_empty() { continue; }
            // trace in filtered terms
            let trace_filtered: Vec<usize> = branches[bi].trace.iter().filter_map(|o| filtered_index.get(o).copied()).collect();
            if trace_filtered.is_empty() { continue; }
            branches[bi].first_assign_filtered = Some(trace_filtered[0]);
            // source fallback from merges (trace order)
            let mut fallback: Option<usize> = None;
            for &orig in &branches[bi].trace {
                let c = &all_commits[orig];
                if c.parents.len() > 1 {
                    for p in c.parents.iter().skip(1) {
                        if let Some(&pidx) = index_map.get(p) {
                            if let Some(pb) = all_commits[pidx].branch {
                                if pb != bi { fallback = Some(order_groups[pb]); }
                            }
                        }
                    }
                }
            }
            // endpoint
            let last_orig = *branches[bi].trace.last().unwrap();
            let last_commit = &all_commits[last_orig];
            let mut source = fallback;
            let mut range_end: Option<usize> = None;
            if last_commit.parents.is_empty() {
                range_end = filtered_index.get(&last_orig).copied();
            } else {
                let poid = last_commit.parents[0];
                if let Some(&pidx) = index_map.get(&poid) {
                    if let Some(pb) = all_commits[pidx].branch {
                        if pb != bi { source = Some(order_groups[pb]); }
                        if let Some(&pf) = filtered_index.get(&pidx) {
                            range_end = Some(pf.saturating_sub(1));
                        } else {
                            range_end = None;
                        }
                    } else {
                        range_end = None;
                    }
                } else {
                    range_end = None;
                }
            }
            // range start
            let range_start = if branches[bi].merge_created {
                if let Some(mci) = branches[bi].merge_commit_idx {
                    if let Some(&mf) = filtered_index.get(&mci) { Some(mf + 1) } else { Some(trace_filtered[0]) }
                } else { Some(trace_filtered[0]) }
            } else { Some(trace_filtered[0]) };
            branches[bi].range = (range_start, range_end);
            branches[bi].source_group = source;
            // target
            if branches[bi].merge_created {
                let mut tgt = None;
                if let Some(mci) = branches[bi].merge_commit_idx {
                    if let Some(tb) = all_commits[mci].branch {
                        if tb != bi { tgt = Some(order_groups[tb]); }
                    }
                }
                branches[bi].target_group = tgt;
            } else {
                branches[bi].target_group = None;
            }
        }

        // colors (eager, may panic on empty list like original)
        for (idx, b) in branches.iter_mut().enumerate() {
            let tlist = settings.model.terminal_list(&b.match_name);
            let tcol_str = &tlist[idx % tlist.len()];
            b.term_color = parse_terminal_color(tcol_str)?;
            let slist = settings.model.svg_list(&b.match_name);
            let scol = &slist[idx % slist.len()];
            b.svg_color = scol.clone();
        }

        // column assignment
        {
            let group_count = settings.model.order.len() + 1;
            let mut occupied: Vec<Vec<Vec<(usize, usize)>>> = vec![Vec::new(); group_count];
            struct SortItem { branch: usize, start: usize, end: usize, src: usize, tgt: usize, own: usize }
            let mut items: Vec<SortItem> = Vec::new();
            for (bi, b) in branches.iter().enumerate() {
                if let (Some(start), _) = b.range {
                    let end = b.range.1.unwrap_or(n_filtered);
                    let own = order_groups[bi];
                    let src = b.source_group.unwrap_or(own);
                    let tgt = b.target_group.unwrap_or(own);
                    items.push(SortItem { branch: bi, start, end, src, tgt, own });
                }
            }
            items.sort_by_key(|it| (std::cmp::max(it.src, it.tgt), it.end.saturating_sub(it.start), it.start));
            let mut within: HashMap<usize, usize> = HashMap::new();
            for it in &items {
                let cols = &mut occupied[it.own];
                let mut chosen: Option<usize> = None;
                for (ci, ranges) in cols.iter().enumerate() {
                    let overlaps = ranges.iter().any(|(s, e)| it.start <= *e && *s <= it.end);
                    if !overlaps { chosen = Some(ci); break; }
                }
                let ci = match chosen {
                    Some(ci) => { cols[ci].push((it.start, it.end)); ci }
                    None => { cols.push(vec![(it.start, it.end)]); cols.len() - 1 }
                };
                within.insert(it.branch, ci);
            }
            let mut offsets = vec![0usize; group_count];
            let mut acc = 0usize;
            for g in 0..group_count { offsets[g] = acc; acc += occupied[g].len(); }
            for (bi, ci) in within {
                branches[bi].column = Some(offsets[order_groups[bi]] + ci);
            }
        }

        // visual starts/ends
        for bi in 0..branches.len() {
            if branches[bi].trace.is_empty() { continue; }
            let first_f = branches[bi].first_assign_filtered;
            // earliest merge where this branch is secondary parent (filtered)
            let mut visual_start = first_f;
            for (fidx, c) in filtered_commits.iter().enumerate() {
                if c.parents.len() > 1 {
                    for p in c.parents.iter().skip(1) {
                        if let Some(&p_orig) = index_map.get(p) {
                            if let Some(&pf) = filtered_index.get(&p_orig) {
                                if filtered_commits[pf].branch == Some(bi) {
                                    visual_start = Some(match visual_start { Some(v) => v.min(fidx), None => fidx });
                                }
                            }
                        }
                    }
                }
            }
            branches[bi].visual_start_filtered = visual_start;
            branches[bi].visual_end_filtered = Some(match branches[bi].range.1 { Some(e) => e, None => if n_filtered == 0 { 0 } else { n_filtered - 1 } });
        }

        let max_column = branches.iter().filter(|b| b.range.0.is_some()).filter_map(|b| b.column).max().unwrap_or(0);

        Ok(GitGraph { commits: filtered_commits, branches, head_branch, head_oid, head_is_branch, max_column })
    }
}

fn sig_info(sig: &git2::Signature) -> SigInfo {
    let when = sig.when();
    SigInfo { name: String::from_utf8_lossy(sig.name_bytes().unwrap_or(b"")).to_string(), email: String::from_utf8_lossy(sig.email_bytes().unwrap_or(b"")).to_string(), seconds: when.seconds(), offset_minutes: when.offset_minutes() }
}

// ---------- Formatting ----------
type Frag = (String, Option<u8>);
type TextLine = Vec<Frag>;
fn plain_line(line: &TextLine) -> String { line.iter().map(|(s, _)| s.as_str()).collect() }
fn frag(s: impl Into<String>, color: Option<u8>) -> Frag { (s.into(), color) }

fn format_date(sig: &SigInfo) -> String {
    let offset = FixedOffset::east_opt(sig.offset_minutes * 60).unwrap_or(FixedOffset::east_opt(0).unwrap());
    match offset.timestamp_opt(sig.seconds, 0) {
        chrono::LocalResult::Single(dt) => dt.format("%a %b %e %H:%M:%S %Y %z").to_string(),
        _ => {
            let dt = DateTime::<Utc>::from_timestamp(sig.seconds, 0).unwrap_or(DateTime::<Utc>::from_timestamp(0, 0).unwrap());
            dt.format("%a %b %e %H:%M:%S %Y %z").to_string()
        }
    }
}
fn format_date_short(sig: &SigInfo) -> String {
    let offset = FixedOffset::east_opt(sig.offset_minutes * 60).unwrap_or(FixedOffset::east_opt(0).unwrap());
    match offset.timestamp_opt(sig.seconds, 0) {
        chrono::LocalResult::Single(dt) => dt.format("%Y-%m-%d").to_string(),
        _ => {
            let dt = DateTime::<Utc>::from_timestamp(sig.seconds, 0).unwrap_or(DateTime::<Utc>::from_timestamp(0, 0).unwrap());
            dt.format("%Y-%m-%d").to_string()
        }
    }
}
fn relative_date(sig: &SigInfo) -> String {
    let now = Utc::now().timestamp();
    let diff = now - sig.seconds;
    if diff < 60 { format!("{} seconds ago", diff) }
    else if diff < 3600 { format!("{} minutes ago", diff / 60) }
    else if diff < 86400 { format!("{} hours ago", diff / 3600) }
    else if diff < 7 * 86400 { format!("{} days ago", diff / 86400) }
    else if diff < 28 * 86400 { format!("{} weeks ago", diff / (7 * 86400)) }
    else if diff < 360 * 86400 { format!("{} months ago", diff / (30 * 86400)) }
    else { format!("{} years ago", diff / (365 * 86400)) }
}

fn refs_fragments(graph: &GitGraph, commit: &CommitData) -> TextLine {
    // returns fragments for %d expansion (including leading space if any)
    let mut branch_names: Vec<(String, u8, bool)> = Vec::new(); // name, color, is_head_branch
    let mut tag_names: Vec<String> = Vec::new();
    for b in &graph.branches {
        if b.head_oid == Some(commit.oid) {
            match b.kind {
                Some(RefKind::Branch) => {
                    let is_head = graph.head_is_branch && graph.head_branch.as_deref() == Some(b.name.as_str());
                    branch_names.push((b.name.clone(), b.term_color, is_head));
                }
                Some(RefKind::Tag) => {
                    let tname = b.name.strip_prefix("tags/").unwrap_or(&b.name).to_string();
                    tag_names.push(tname);
                }
                None => {}
            }
        }
    }
    let is_detached_head_here = !graph.head_is_branch && graph.head_oid == Some(commit.oid);
    if branch_names.is_empty() && tag_names.is_empty() && !is_detached_head_here {
        return Vec::new();
    }
    let commit_branch_color = commit.branch.map(|bi| graph.branches[bi].term_color).unwrap_or(7);
    let mut out: TextLine = Vec::new();
    out.push(frag(" ", None));
    if is_detached_head_here {
        out.push(frag("HEAD ->", Some(14)));
        if !branch_names.is_empty() || !tag_names.is_empty() { out.push(frag(" ", None)); }
    }
    if !branch_names.is_empty() {
        out.push(frag("(", None));
        for (i, (name, color, is_head)) in branch_names.iter().enumerate() {
            if i > 0 { out.push(frag(", ", None)); }
            if *is_head && !is_detached_head_here {
                out.push(frag("HEAD ->", Some(14)));
                out.push(frag(" ", None));
            }
            out.push(frag(name.clone(), Some(*color)));
        }
        out.push(frag(")", None));
    }
    if !tag_names.is_empty() {
        if !branch_names.is_empty() { out.push(frag(" ", None)); }
        out.push(frag("[", None));
        for (i, t) in tag_names.iter().enumerate() {
            if i > 0 { out.push(frag(", ", None)); }
            out.push(frag(t.clone(), Some(commit_branch_color)));
        }
        out.push(frag("]", None));
    }
    out
}
fn refs_plain(graph: &GitGraph, commit: &CommitData) -> String { plain_line(&refs_fragments(graph, commit)) }

fn short_hash(oid: &Oid) -> String { let s = oid.to_string(); s.chars().take(7).collect() }

fn format_commit_lines(graph: &GitGraph, idx: usize, format: &str) -> Vec<TextLine> {
    let commit = &graph.commits[idx];
    match format {
        "oneline" | "o" => {
            let mut line: TextLine = Vec::new();
            line.push(frag(short_hash(&commit.oid), Some(11)));
            line.extend(refs_fragments(graph, commit));
            line.push(frag(" ", None));
            line.push(frag(commit.summary.clone(), None));
            vec![line]
        }
        "short" | "s" => {
            let mut lines: Vec<TextLine> = Vec::new();
            let mut l: TextLine = vec![frag("commit ", None), frag(commit.oid.to_string(), Some(11))];
            l.extend(refs_fragments(graph, commit)); lines.push(l);
            if commit.parents.len() > 1 {
                let merges = commit.parents.iter().map(|p| short_hash(p)).collect::<Vec<_>>().join(" ");
                lines.push(vec![frag(format!("Merge: {}", merges), None)]);
            }
            lines.push(vec![frag(format!("Author: {} <{}>", commit.author.name, commit.author.email), None)]);
            lines.push(vec![frag("", None)]);
            lines.push(vec![frag(format!("    {}", commit.summary), None)]);
            lines.push(vec![frag("", None)]);
            lines
        }
        "medium" | "m" => {
            let mut lines: Vec<TextLine> = Vec::new();
            let mut l: TextLine = vec![frag("commit ", None), frag(commit.oid.to_string(), Some(11))];
            l.extend(refs_fragments(graph, commit)); lines.push(l);
            if commit.parents.len() > 1 {
                let merges = commit.parents.iter().map(|p| short_hash(p)).collect::<Vec<_>>().join(" ");
                lines.push(vec![frag(format!("Merge: {}", merges), None)]);
            }
            lines.push(vec![frag(format!("Author: {} <{}>", commit.author.name, commit.author.email), None)]);
            lines.push(vec![frag(format!("Date:   {}", format_date(&commit.author)), None)]);
            lines.push(vec![frag("", None)]);
            for ml in commit.message.lines() {
                if ml.is_empty() { lines.push(vec![frag("", None)]); } else { lines.push(vec![frag(format!("    {}", ml), None)]); }
            }
            lines.push(vec![frag("", None)]);
            lines
        }
        "full" | "f" => {
            let mut lines: Vec<TextLine> = Vec::new();
            let mut l: TextLine = vec![frag("commit ", None), frag(commit.oid.to_string(), Some(11))];
            l.extend(refs_fragments(graph, commit)); lines.push(l);
            if commit.parents.len() > 1 {
                let merges = commit.parents.iter().map(|p| short_hash(p)).collect::<Vec<_>>().join(" ");
                lines.push(vec![frag(format!("Merge: {}", merges), None)]);
            }
            lines.push(vec![frag(format!("Author: {} <{}>", commit.author.name, commit.author.email), None)]);
            lines.push(vec![frag(format!("Commit: {} <{}>", commit.committer.name, commit.committer.email), None)]);
            lines.push(vec![frag(format!("Date:   {}", format_date(&commit.author)), None)]);
            lines.push(vec![frag("", None)]);
            for ml in commit.message.lines() {
                if ml.is_empty() { lines.push(vec![frag("", None)]); } else { lines.push(vec![frag(format!("    {}", ml), None)]); }
            }
            lines.push(vec![frag("", None)]);
            lines
        }
        _ => format_custom(graph, commit, format),
    }
}

fn placeholder_expansion(graph: &GitGraph, commit: &CommitData, token: &str) -> TextLine {
    match token {
        "H" => vec![frag(commit.oid.to_string(), Some(11))],
        "h" => vec![frag(short_hash(&commit.oid), Some(11))],
        "P" => vec![frag(commit.parents.iter().map(|p| p.to_string()).collect::<Vec<_>>().join(" "), None)],
        "p" => vec![frag(commit.parents.iter().map(|p| short_hash(p)).collect::<Vec<_>>().join(" "), None)],
        "d" => refs_fragments(graph, commit),
        "s" => vec![frag(commit.summary.clone(), None)],
        "b" => vec![frag(commit.body.clone(), None)],
        "B" => vec![frag(commit.message.clone(), None)],
        "an" => vec![frag(commit.author.name.clone(), None)],
        "ae" => vec![frag(commit.author.email.clone(), None)],
        "ad" => vec![frag(format_date(&commit.author), None)],
        "as" => vec![frag(format_date_short(&commit.author), None)],
        "ar" => vec![frag(relative_date(&commit.author), None)],
        "cn" => vec![frag(commit.committer.name.clone(), None)],
        "ce" => vec![frag(commit.committer.email.clone(), None)],
        "cd" => vec![frag(format_date(&commit.committer), None)],
        "cs" => vec![frag(format_date_short(&commit.committer), None)],
        "cr" => vec![frag(relative_date(&commit.committer), None)],
        _ => Vec::new(),
    }
}

fn format_custom(graph: &GitGraph, commit: &CommitData, format: &str) -> Vec<TextLine> {
    // Build lines, splitting on %n and on newlines inside expansions, dropping empty segments from expansions.
    let mut lines: Vec<TextLine> = Vec::new();
    let mut current: TextLine = Vec::new();
    let mut pending_break = false;
    let chars: Vec<char> = format.chars().collect();
    let mut i = 0usize;
    fn push_frag(current: &mut TextLine, f: Frag) {
        if f.0.is_empty() { return; }
        if let Some(last) = current.last_mut() {
            if last.1 == f.1 { last.0.push_str(&f.0); return; }
        }
        current.push(f);
    }
    fn append_line_content(lines: &mut Vec<TextLine>, current: &mut TextLine, pending: &mut bool, content: TextLine) {
        if content.iter().all(|(s, _)| s.is_empty()) { return; }
        if *pending {
            if !current.is_empty() || !lines.is_empty() {
                // only break if current has content or we already have lines and current is a started line
                if !current.is_empty() {
                    lines.push(std::mem::take(current));
                }
            }
            *pending = false;
        }
        for f in content { push_frag(current, f); }
    }
    // helper to append expansion text that may contain newlines
    let append_expansion = |lines: &mut Vec<TextLine>, current: &mut TextLine, pending: &mut bool, exp: TextLine| {
        // split exp fragments by '\n'
        let plain = plain_line(&exp);
        if plain.is_empty() { return; }
        // build segments preserving colors: iterate frags char by char
        let mut segments: Vec<TextLine> = Vec::new();
        let mut seg: TextLine = Vec::new();
        for (text, col) in &exp {
            let mut start = 0usize;
            for (pos, ch) in text.char_indices() {
                if ch == '\n' {
                    if start < pos { 
                        let part = &text[start..pos];
                        if let Some(last) = seg.last_mut().filter(|l: &&mut (String, Option<u8>)| l.1 == *col) { last.0.push_str(part); } else { seg.push(frag(part.to_string(), *col)); }
                    }
                    segments.push(std::mem::take(&mut seg));
                    start = pos + 1;
                }
            }
            if start < text.len() {
                let part = &text[start..];
                if let Some(last) = seg.last_mut().filter(|l: &&mut (String, Option<u8>)| l.1 == *col) { last.0.push_str(part); } else { seg.push(frag(part.to_string(), *col)); }
            } else if text.is_empty() {
                // nothing
            }
        }
        segments.push(seg);
        let mut first = true;
        for segment in segments {
            if plain_line(&segment).is_empty() { 
                // empty segment marks a break for the next non-empty segment, but don't create empty line
                if !first { /* set a marker via pending */ }
                // we handle by setting pending if we have already appended something in this expansion
                if !first { *pending = true; }
                first = false;
                continue;
            }
            if first {
                append_line_content(lines, current, pending, segment);
                first = false;
            } else {
                // force a break
                *pending = true;
                append_line_content(lines, current, pending, segment);
            }
        }
    };

    while i < chars.len() {
        if chars[i] == '%' {
            // look ahead
            let mut j = i + 1;
            let mut modifier: Option<char> = None;
            if j < chars.len() && (chars[j] == '+' || chars[j] == '-' || chars[j] == ' ') { modifier = Some(chars[j]); j += 1; }
            // token
            let two: String = if j + 1 < chars.len() { chars[j..j+2].iter().collect() } else { String::new() };
            let one: Option<char> = if j < chars.len() { Some(chars[j]) } else { None };
            let token: Option<String> = if ["an","ae","ad","as","ar","cn","ce","cd","cs","cr"].contains(&two.as_str()) {
                Some(two.clone())
            } else if let Some(c) = one {
                if "HhPpdsbBn".contains(c) { Some(c.to_string()) } else { None }
            } else { None };
            if let Some(tok) = token {
                let is_newline = tok == "n";
                let consumed = if tok.len() == 2 { j + 2 } else { j + 1 };
                if is_newline {
                    pending_break = true;
                } else {
                    let exp = placeholder_expansion(graph, commit, &tok);
                    let exp_plain = plain_line(&exp);
                    match modifier {
                        Some('+') => {
                            if !exp_plain.is_empty() { pending_break = true; append_expansion(&mut lines, &mut current, &mut pending_break, exp); }
                        }
                        Some('-') => {
                            if exp_plain.is_empty() {
                                pending_break = false;
                                // strip trailing newlines from current plain text
                                for f in current.iter_mut() { while f.0.ends_with('\n') { f.0.pop(); } }
                                current.retain(|f| !f.0.is_empty());
                            } else {
                                append_expansion(&mut lines, &mut current, &mut pending_break, exp);
                            }
                        }
                        Some(' ') => {
                            if !exp_plain.is_empty() {
                                // insert a space before expansion (unless pending break handling will add? original inserts into same line)
                                // If pending break, the space goes after break via expansion handling; we emulate by adding a plain space frag first through append mechanism
                                if pending_break {
                                    // will break, then add space as content
                                    append_line_content(&mut lines, &mut current, &mut pending_break, vec![frag(" ", None)]);
                                    append_expansion(&mut lines, &mut current, &mut pending_break, exp);
                                } else {
                                    push_frag(&mut current, frag(" ", None));
                                    append_expansion(&mut lines, &mut current, &mut pending_break, exp);
                                }
                            }
                        }
                        _ => {
                            append_expansion(&mut lines, &mut current, &mut pending_break, exp);
                        }
                    }
                }
                i = consumed;
                continue;
            } else {
                // literal %
                // append single '%' as content
                let mut tmp = vec![frag("%", None)];
                append_line_content(&mut lines, &mut current, &mut pending_break, std::mem::take(&mut tmp));
                i += 1;
                continue;
            }
        } else {
            // literal run until next %
            let start = i;
            while i < chars.len() && chars[i] != '%' { i += 1; }
            let text: String = chars[start..i].iter().collect();
            append_line_content(&mut lines, &mut current, &mut pending_break, vec![frag(text, None)]);
        }
    }
    if !current.is_empty() || lines.is_empty() {
        lines.push(current);
    }
    lines
}

// ---------- Wrapping ----------
#[derive(Clone)]
struct DChar { ch: char, color: Option<u8>, width: usize }
fn line_to_dchars(line: &TextLine) -> Vec<DChar> {
    let mut out = Vec::new();
    for (text, col) in line {
        for ch in text.chars() {
            let w = UnicodeWidthChar::width(ch).unwrap_or(0);
            out.push(DChar { ch, color: *col, width: w });
        }
    }
    out
}
fn dchars_to_line(chars: &[DChar]) -> TextLine {
    let mut out: TextLine = Vec::new();
    for dc in chars {
        if let Some(last) = out.last_mut().filter(|l: &&mut (String, Option<u8>)| l.1 == dc.color) { last.0.push(dc.ch); } else { out.push(frag(dc.ch.to_string(), dc.color)); }
    }
    if out.is_empty() { out.push(frag("", None)); }
    out
}
fn wrap_line(line: &TextLine, wrap: &WrapConfig) -> Vec<TextLine> {
    let width = match wrap.width { None => return vec![line.clone()], Some(w) => w };
    let dchars = line_to_dchars(line);
    if dchars.is_empty() { return vec![vec![frag("", None)]]; }
    let indent1 = wrap.indent1;
    let indent2 = wrap.indent2;
    let cap_first = width.saturating_sub(indent1).max(1);
    let cap_sub = width.saturating_sub(indent2).max(1);
    let chunk_cap = cap_sub;
    // tokenize into words (sequences of non-space) with separator widths (spaces before)
    struct FragWord { chars: Vec<DChar>, sep_before: usize, sep_chars: Vec<DChar> }
    let mut words: Vec<FragWord> = Vec::new();
    let mut idx = 0usize;
    // leading spaces
    let mut leading_sep: Vec<DChar> = Vec::new();
    while idx < dchars.len() && dchars[idx].ch == ' ' { leading_sep.push(dchars[idx].clone()); idx += 1; }
    let mut first = true;
    while idx < dchars.len() {
        let mut sep_chars: Vec<DChar> = Vec::new();
        if !first {
            while idx < dchars.len() && dchars[idx].ch == ' ' { sep_chars.push(dchars[idx].clone()); idx += 1; }
            if idx >= dchars.len() {
                // trailing spaces: attach to last word as sep? Keep as a pseudo word
                if !sep_chars.is_empty() {
                    words.push(FragWord { chars: Vec::new(), sep_before: 0, sep_chars });
                }
                break;
            }
        }
        let word_start = idx;
        while idx < dchars.len() && dchars[idx].ch != ' ' { idx += 1; }
        let word_chars = dchars[word_start..idx].to_vec();
        let sep_before = if first { leading_sep.len() } else { sep_chars.len() };
        let sep_for_word = if first { leading_sep.clone() } else { sep_chars };
        words.push(FragWord { chars: word_chars, sep_before, sep_chars: sep_for_word });
        first = false;
    }
    if words.is_empty() {
        // line was all spaces
        return vec![line.clone()];
    }
    // split long words into chunks of chunk_cap
    struct Piece { chars: Vec<DChar>, sep_before: usize, sep_chars: Vec<DChar>, is_first_of_word: bool }
    let mut pieces: Vec<Piece> = Vec::new();
    for w in words {
        if w.chars.is_empty() {
            // trailing spaces piece
            pieces.push(Piece { chars: w.sep_chars.clone(), sep_before: 0, sep_chars: Vec::new(), is_first_of_word: true });
            continue;
        }
        let total_w: usize = w.chars.iter().map(|c| c.width).sum();
        if total_w <= chunk_cap {
            pieces.push(Piece { chars: w.chars, sep_before: w.sep_before, sep_chars: w.sep_chars, is_first_of_word: true });
        } else {
            let mut cur: Vec<DChar> = Vec::new();
            let mut cur_w = 0usize;
            let mut first_chunk = true;
            for dc in w.chars {
                if cur_w + dc.width > chunk_cap && !cur.is_empty() {
                    pieces.push(Piece { chars: std::mem::take(&mut cur), sep_before: if first_chunk { w.sep_before } else { 0 }, sep_chars: if first_chunk { w.sep_chars.clone() } else { Vec::new() }, is_first_of_word: first_chunk });
                    first_chunk = false;
                    cur_w = 0;
                }
                cur.push(dc.clone());
                cur_w += dc.width;
            }
            if !cur.is_empty() {
                pieces.push(Piece { chars: cur, sep_before: if first_chunk { w.sep_before } else { 0 }, sep_chars: if first_chunk { w.sep_chars } else { Vec::new() }, is_first_of_word: first_chunk });
            }
        }
    }
    // greedy packing
    let mut result: Vec<TextLine> = Vec::new();
    let mut cur_chars: Vec<DChar> = Vec::new();
    let mut cur_width = 0usize;
    let mut line_no = 0usize;
    let capacity = |ln: usize| if ln == 0 { cap_first } else { cap_sub };
    for piece in pieces {
        let piece_w: usize = piece.chars.iter().map(|c| c.width).sum();
        if cur_chars.is_empty() {
            // start new line with this piece (include its sep_before if it's leading spaces of line? For first line, leading spaces are preserved; for wrapped lines, sep is discarded)
            if line_no == 0 && piece.is_first_of_word {
                // include separator spaces (leading) as chars
                for sc in &piece.sep_chars { cur_chars.push(sc.clone()); cur_width += sc.width; }
            }
            cur_chars.extend(piece.chars.iter().cloned());
            cur_width += piece_w;
        } else {
            let sep_w = piece.sep_before;
            if cur_width + sep_w + piece_w <= capacity(line_no) {
                for sc in &piece.sep_chars { cur_chars.push(sc.clone()); }
                // sep_chars length may not equal sep_w in weird cases; ensure width accounting uses sep_w
                cur_width += sep_w + piece_w;
                cur_chars.extend(piece.chars.iter().cloned());
            } else {
                // emit cur
                let indent = if line_no == 0 { indent1 } else { indent2 };
                let mut out_chars: Vec<DChar> = Vec::new();
                for _ in 0..indent { out_chars.push(DChar { ch: ' ', color: None, width: 1 }); }
                out_chars.extend(cur_chars.iter().cloned());
                result.push(dchars_to_line(&out_chars));
                line_no += 1;
                cur_chars = Vec::new();
                cur_width = 0;
                // start with piece (discard separator)
                cur_chars.extend(piece.chars.iter().cloned());
                cur_width = piece_w;
            }
        }
    }
    // last
    let indent = if line_no == 0 { indent1 } else { indent2 };
    let mut out_chars: Vec<DChar> = Vec::new();
    for _ in 0..indent { out_chars.push(DChar { ch: ' ', color: None, width: 1 }); }
    out_chars.extend(cur_chars.iter().cloned());
    result.push(dchars_to_line(&out_chars));
    result
}
fn wrap_commit_lines(lines: Vec<TextLine>, wrap: &WrapConfig) -> Vec<TextLine> {
    if wrap.width.is_none() { return lines; }
    let mut out = Vec::new();
    for l in lines { out.extend(wrap_line(&l, wrap)); }
    out
}

// ---------- Text graph rendering ----------
#[derive(Clone, Copy, PartialEq, Eq)]
enum SegKind { Space, Horiz, ArrowLeft, ArrowRight }
#[derive(Clone)]
struct Cell {
    branch: Option<usize>,
    up: bool, down: bool, left: bool, right: bool,
    dot: bool, merge_dot: bool,
}
impl Cell { fn empty() -> Self { Cell { branch: None, up: false, down: false, left: false, right: false, dot: false, merge_dot: false } } }
#[derive(Clone)]
struct GraphRow {
    cells: Vec<Cell>,
    segs: Vec<(SegKind, Option<usize>)>, // between cells
    text: TextLine,
}

struct Renderer<'a> {
    graph: &'a GitGraph,
    settings: &'a Settings,
}
impl<'a> Renderer<'a> {
    fn branch_col(&self, bi: usize) -> usize { self.graph.branches[bi].column.unwrap_or(0) }
    fn active_branch_at(&self, col: usize, row: usize) -> Option<usize> {
        let mut best: Option<usize> = None;
        let mut best_score = -1i32;
        for (bi, b) in self.graph.branches.iter().enumerate() {
            if b.column != Some(col) { continue; }
            let vs = match b.visual_start_filtered { Some(v) => v, None => continue };
            let ve = match b.visual_end_filtered { Some(v) => v, None => continue };
            if row < vs || row > ve { continue; }
            if self.settings.sparse {
                // if visual start is a merge (vs < first_assign), not active on merge row itself
                if let Some(fa) = b.first_assign_filtered { if vs < fa && row == vs { continue; } }
            }
            let mut score = 0;
            if let Some(fa) = b.first_assign_filtered { if row >= fa { score += 10; } }
            if b.range.0.map(|s| row >= s).unwrap_or(false) { score += 1; }
            if score > best_score { best_score = score; best = Some(bi); }
        }
        best
    }
    fn active_between(&self, col: usize, after_row: usize) -> Option<usize> {
        // branches active in interval after commit after_row (before after_row+1)
        let mut best: Option<usize> = None;
        for (bi, b) in self.graph.branches.iter().enumerate() {
            if b.column != Some(col) { continue; }
            let vs = b.visual_start_filtered?;
            let ve = b.visual_end_filtered?;
            // active after row if vs <= after_row and ve > after_row, or sparse start at after_row
            let started = vs <= after_row || (self.settings.sparse && vs == after_row);
            if started && ve > after_row { best = Some(bi); }
        }
        best
    }
    fn filtered_parent_idx(&self, commit_idx: usize, parent_oid: &Oid) -> Option<usize> {
        self.graph.commits.iter().position(|c| c.oid == *parent_oid)
    }
    fn build_rows(&self, wrapped: &Vec<Vec<TextLine>>) -> Vec<GraphRow> {
        let g = self.graph;
        let n = g.commits.len();
        let max_col = g.max_column;
        let mut rows: Vec<GraphRow> = Vec::new();
        if n == 0 { return rows; }
        for i in 0..n {
            // ---- segment for commit i ----
            let mut segment: Vec<GraphRow> = Vec::new();
            // commit row
            let commit = &g.commits[i];
            let commit_bi = commit.branch.unwrap();
            let commit_col = self.branch_col(commit_bi);
            let mut cells: Vec<Cell> = (0..=max_col).map(|_| Cell::empty()).collect();
            let mut segs: Vec<(SegKind, Option<usize>)> = (0..max_col).map(|_| (SegKind::Space, None)).collect();
            for c in 0..=max_col {
                if c == commit_col {
                    let mut cell = Cell::empty();
                    cell.branch = Some(commit_bi);
                    cell.dot = true;
                    cell.merge_dot = commit.parents.len() > 1;
                    cells[c] = cell;
                } else if let Some(bi) = self.active_branch_at(c, i) {
                    let b = &g.branches[bi];
                    let mut cell = Cell::empty();
                    cell.branch = Some(bi);
                    let vs = b.visual_start_filtered.unwrap();
                    let ve = b.visual_end_filtered.unwrap();
                    cell.up = vs < i;
                    cell.down = ve > i;
                    // if trace starts here due to compact merge, up false (handled)
                    cells[c] = cell;
                }
            }
            // merge horizontals (compact)
            if !self.settings.sparse && commit.parents.len() > 1 {
                for poid in commit.parents.iter().skip(1) {
                    if let Some(pidx) = self.filtered_parent_idx(i, poid) {
                        let p_commit = &g.commits[pidx];
                        if let Some(p_bi) = p_commit.branch {
                            let p_col = self.branch_col(p_bi);
                            if p_col == commit_col { continue; }
                            let (lo, hi) = if p_col < commit_col { (p_col, commit_col) } else { (commit_col, p_col) };
                            for s in lo..hi {
                                let kind = if p_col > commit_col && s == commit_col { SegKind::ArrowLeft } else if p_col < commit_col && s == commit_col - 1 { SegKind::ArrowRight } else { SegKind::Horiz };
                                segs[s] = (kind, Some(p_bi));
                            }
                            // target cell
                            {
                                let cell = &mut cells[p_col];
                                cell.branch = Some(p_bi);
                                cell.down = true;
                                if p_col > commit_col { cell.left = true; } else { cell.right = true; }
                                // up remains as set if already active
                            }
                            // crossing cells
                            for c in (lo + 1)..hi {
                                if c == p_col { continue; }
                                let cell = &mut cells[c];
                                cell.left = true; cell.right = true;
                                if cell.branch.is_none() { cell.branch = Some(p_bi); }
                            }
                            // also intermediate segment cells main char for inactive columns between lo..hi (excluding endpoints)
                            for c in lo..=hi {
                                if c == commit_col || c == p_col { continue; }
                                let cell = &mut cells[c];
                                cell.left = true; cell.right = true;
                                if cell.branch.is_none() { cell.branch = Some(p_bi); }
                            }
                        }
                    }
                }
            }
            segment.push(GraphRow { cells, segs, text: vec![frag("", None)] });
            // boundary rows between i and i+1
            if i + 1 < n {
                if let Some(brow) = self.boundary_row(i) { segment.push(brow); }
            }
            // expand with dummy rows for text
            let text_lines = &wrapped[i];
            let need = text_lines.len();
            while segment.len() < need {
                segment.push(self.dummy_row(i));
            }
            for (ri, row) in segment.iter_mut().enumerate() {
                if ri < need { row.text = text_lines[ri].clone(); }
            }
            rows.extend(segment);
        }
        rows
    }
    fn boundary_row(&self, i: usize) -> Option<GraphRow> {
        let g = self.graph;
        let max_col = g.max_column;
        #[derive(Clone)]
        struct Movement { source: usize, target: usize, branch: usize, is_start: bool }
        let mut movements: Vec<Movement> = Vec::new();
        // ending movements
        for (bi, b) in g.branches.iter().enumerate() {
            if b.range.1 == Some(i) {
                if let Some(last_orig_trace) = b.trace.last() {
                    // parent of last trace commit in filtered terms
                    let _ = last_orig_trace;
                }
                // check parent of last assigned filtered commit
                // find last assigned filtered index for this branch
                // use trace: last assigned commit's primary parent filtered index == i+1
                if let Some(&last_f) = b.trace.iter().filter_map(|o| self.filtered_of_original(*o)).collect::<Vec<_>>().last() {
                    let lc = &g.commits[last_f];
                    if !lc.parents.is_empty() {
                        if let Some(pidx) = self.filtered_parent_idx(last_f, &lc.parents[0]) {
                            if pidx == i + 1 {
                                let target_col = g.commits[pidx].branch.map(|pb| self.branch_col(pb)).unwrap();
                                if b.column.unwrap() != target_col {
                                    movements.push(Movement { source: b.column.unwrap(), target: target_col, branch: bi, is_start: false });
                                }
                            }
                        }
                    }
                }
            }
        }
        // sparse starting movements
        if self.settings.sparse {
            let commit = &g.commits[i];
            if commit.parents.len() > 1 {
                let commit_col = self.branch_col(commit.branch.unwrap());
                for poid in commit.parents.iter().skip(1) {
                    if let Some(pidx) = self.filtered_parent_idx(i, poid) {
                        if let Some(p_bi) = g.commits[pidx].branch {
                            let p_col = self.branch_col(p_bi);
                            if p_col != commit_col {
                                movements.push(Movement { source: commit_col, target: p_col, branch: p_bi, is_start: true });
                            }
                        }
                    }
                }
            }
        }
        if movements.is_empty() { return None; }
        let mut cells: Vec<Cell> = (0..=max_col).map(|_| Cell::empty()).collect();
        let mut segs: Vec<(SegKind, Option<usize>)> = (0..max_col).map(|_| (SegKind::Space, None)).collect();
        // segs
        for mv in &movements {
            let (lo, hi) = if mv.source < mv.target { (mv.source, mv.target) } else { (mv.target, mv.source) };
            for s in lo..hi {
                // choose branch: prefer movement whose source is adjacent
                let prev = &segs[s];
                if prev.0 == SegKind::Space {
                    segs[s] = (if mv.is_start && s == (if mv.target > mv.source { mv.source } else { mv.source - 1 }) {
                        // sparse arrow segment adjacent to source (merge branch)
                        if mv.target > mv.source { SegKind::ArrowLeft } else { SegKind::ArrowRight }
                    } else { SegKind::Horiz }, Some(mv.branch));
                }
            }
            // For sparse, the segment adjacent to merge branch should be arrow pointing toward merge branch line:
            // source is merge col, target is secondary. If target > source, arrow is at s=source and should be '<' (pointing left toward source line)
            // already handled: when target>source, s==source => ArrowLeft; when target<source, s==source-1 => ArrowRight.
            // For non-sparse ending movements, segments are plain horiz (our code above may incorrectly arrow for is_start only)
        }
        for c in 0..=max_col {
            let above = self.active_branch_at(c, i);
            let below = self.active_branch_at(c, i + 1);
            let mut cell = Cell::empty();
            cell.up = above.is_some();
            cell.down = below.is_some();
            // For sparse start target, above is none but below exists (active_branch_at handles sparse? on row i+1 it's active)
            // For ending source, below is none
            let mut branch_choice: Option<usize> = None;
            for mv in &movements {
                if mv.source == c { cell.left = mv.target < c; cell.right = mv.target > c; branch_choice = Some(mv.branch); }
                if mv.target == c {
                    if mv.target > mv.source { cell.left = true; } else if mv.target < mv.source { cell.right = true; }
                    // target branch is below branch
                    if !mv.is_start { branch_choice = below.or(above); } else { branch_choice = Some(mv.branch); }
                }
                if (mv.source < c && c < mv.target) || (mv.target < c && c < mv.source) { cell.left = true; cell.right = true; }
            }
            if branch_choice.is_none() {
                branch_choice = below.or(above);
                if branch_choice.is_none() {
                    // crossing inactive
                    for mv in &movements {
                        if (mv.source < c && c < mv.target) || (mv.target < c && c < mv.source) { branch_choice = Some(mv.branch); break; }
                    }
                }
            }
            // If this column is a target of an ending movement, its branch should be target branch (below)
            for mv in &movements {
                if mv.target == c && !mv.is_start { branch_choice = below.or(branch_choice); }
            }
            cell.branch = branch_choice;
            cells[c] = cell;
        }
        Some(GraphRow { cells, segs, text: vec![frag("", None)] })
    }
    fn filtered_of_original(&self, orig_idx: usize) -> Option<usize> {
        // original index refers to all_commits order, which is same order as filtered before filtering? We lost mapping.
        // However branch.trace stores original indices; during GitGraph::new, filtered order preserves original order.
        // We can recover by matching: filtered commits are a subsequence. This function is only used in boundary_row
        // where we instead can find last filtered commit assigned to branch directly (see below workaround).
        let _ = orig_idx; None
    }
    fn dummy_row(&self, after_i: usize) -> GraphRow {
        let max_col = self.graph.max_column;
        let mut cells: Vec<Cell> = (0..=max_col).map(|_| Cell::empty()).collect();
        let segs: Vec<(SegKind, Option<usize>)> = (0..max_col).map(|_| (SegKind::Space, None)).collect();
        for c in 0..=max_col {
            let active = if after_i + 1 < self.graph.commits.len() {
                // state before next commit: use active_branch_at for next row but exclude branches that start at next commit as first assign (vs == after_i+1 and not sparse-started)
                let mut cand = self.active_branch_at(c, after_i + 1);
                if let Some(bi) = cand {
                    let b = &self.graph.branches[bi];
                    if b.visual_start_filtered == Some(after_i + 1) {
                        // starts at next commit (its dot) - not active in dummy unless it's a sparse-started or merge-started branch whose trace began earlier
                        if b.first_assign_filtered == Some(after_i + 1) {
                            // check if it was secondary-started earlier
                            let started_earlier = b.visual_start_filtered.map(|vs| vs <= after_i).unwrap_or(false);
                            if !started_earlier { cand = self.active_between(c, after_i); }
                        }
                    }
                }
                // also consider active_between for ending traces that moved
                // Prefer active_between if it exists and differs? We'll use active_between when available for columns that had a movement
                if let Some(ab) = self.active_between(c, after_i) {
                    // ab is branch whose interval spans the gap
                    // use it if cand is none or ab's visual interval includes gap
                    if cand.is_none() { cand = Some(ab); }
                }
                cand
            } else {
                self.active_between(c, after_i)
            };
            if let Some(bi) = active {
                let mut cell = Cell::empty();
                cell.branch = Some(bi);
                cell.up = true; cell.down = true;
                cells[c] = cell;
            }
        }
        GraphRow { cells, segs, text: vec![frag("", None)] }
    }
}

fn shape_char(cell: &Cell, style: Style) -> char {
    if cell.dot { 
        return match style {
            Style::Ascii => if cell.merge_dot { 'o' } else { '*' },
            _ => if cell.merge_dot { '○' } else { '●' },
        };
    }
    let mask = (cell.up as u8) << 3 | (cell.down as u8) << 2 | (cell.left as u8) << 1 | (cell.right as u8);
    // mask bits: up=8 down=4 left=2 right=1
    match (style, mask) {
        (_, 0) => ' ',
        (Style::Ascii, _) => {
            match mask {
                0b1000 | 0b0100 | 0b1100 | 0b1010 | 0b1001 => '|', // up, down, UD, U-left? etc - will refine below
                _ => ascii_shape(mask),
            }
        }
        _ => unicode_shape(mask, style),
    }
}
fn ascii_shape(mask: u8) -> char {
    match mask {
        0 => ' ',
        0b1000 => '|', // up
        0b0100 => '|', // down
        0b0010 => '-', // left
        0b0001 => '-', // right
        0b1100 => '|', // UD
        0b0011 => '-', // LR
        0b0101 => '.', // DR
        0b0110 => '.', // DL
        0b1001 => '\'', // UR
        0b1010 => '\'', // UL
        0b1101 => '|', // UDR
        0b1110 => '|', // UDL
        0b0111 => '+', // DLR
        0b1011 => '+', // ULR
        0b1111 => '+', // all
        _ => ' ',
    }
}
fn unicode_shape(mask: u8, style: Style) -> char {
    let thin = match mask {
        0 => ' ',
        0b1000 => '╵',
        0b0100 => '╷',
        0b0010 => '╴',
        0b0001 => '╶',
        0b1100 => '│',
        0b0011 => '─',
        0b0101 => '┌',
        0b0110 => '┐',
        0b1001 => '└',
        0b1010 => '┘',
        0b1101 => '├',
        0b1110 => '┤',
        0b0111 => '┬',
        0b1011 => '┴',
        0b1111 => '┼',
        _ => ' ',
    };
    match style {
        Style::Thin => thin,
        Style::Round => match thin {
            '┌' => '╭', '┐' => '╮', '└' => '╰', '┘' => '╯', other => other,
        },
        Style::Bold => match thin {
            '│' => '┃', '─' => '━', '┌' => '┏', '┐' => '┓', '└' => '┗', '┘' => '┛',
            '├' => '┣', '┤' => '┫', '┬' => '┳', '┴' => '┻', '┼' => '╋',
            '╵' => '╹', '╷' => '╻', '╴' => '╸', '╶' => '╺', other => other,
        },
        Style::Double => match thin {
            '│' => '║', '─' => '═', '┌' => '╔', '┐' => '╗', '└' => '╚', '┘' => '╝',
            '├' => '╠', '┤' => '╣', '┬' => '╦', '┴' => '╩', '┼' => '╬',
            other => other,
        },
        Style::Ascii => thin, // unreachable
    }
}

fn colorize_char(ch: char, branch: Option<usize>, graph: &GitGraph, use_color: bool) -> String {
    if ch == ' ' || !use_color { return ch.to_string(); }
    if let Some(bi) = branch {
        let code = graph.branches[bi].term_color;
        format!("\x1b[38;5;{}m{}\x1b[0m", code, ch)
    } else { ch.to_string() }
}
fn render_frags(line: &TextLine, use_color: bool) -> String {
    let mut out = String::new();
    for (text, col) in line {
        if text.is_empty() { continue; }
        if use_color {
            if let Some(code) = col { out.push_str(&format!("\x1b[38;5;{}m{}\x1b[0m", code, text)); } else { out.push_str(text); }
        } else { out.push_str(text); }
    }
    out
}

fn render_rows_to_string(rows: &Vec<GraphRow>, graph: &GitGraph, settings: &Settings) -> String {
    let mut out = String::new();
    let max_col = graph.max_column;
    if settings.reverse {
        for row in rows.iter().rev() {
            out.push_str(&render_single_row_reversed(row, graph, settings, max_col));
            out.push('\n');
        }
    } else {
        for row in rows {
            out.push_str(&render_single_row(row, graph, settings));
            out.push('\n');
        }
    }
    out
}
fn render_single_row(row: &GraphRow, graph: &GitGraph, settings: &Settings) -> String {
    let mut s = String::new();
    s.push(' ');
    for c in 0..row.cells.len() {
        let cell = &row.cells[c];
        let ch = shape_char(cell, settings.style);
        s.push_str(&colorize_char(ch, cell.branch, graph, settings.use_color));
        if c < row.segs.len() {
            let (kind, br) = &row.segs[c];
            let sch = match kind { SegKind::Space => ' ', SegKind::Horiz => match settings.style { Style::Bold => '━', Style::Double => '═', Style::Ascii => '-', _ => '─' }, SegKind::ArrowLeft => '<', SegKind::ArrowRight => '>' };
            s.push_str(&colorize_char(sch, *br, graph, settings.use_color));
        }
    }
    s.push_str("  ");
    s.push_str(&render_frags(&row.text, settings.use_color));
    s
}
fn render_single_row_reversed(row: &GraphRow, graph: &GitGraph, settings: &Settings, max_col: usize) -> String {
    // build reversed cells
    let ncell = row.cells.len();
    let mut cells: Vec<Cell> = vec![Cell::empty(); ncell];
    for (old_c, cell) in row.cells.iter().enumerate() {
        let new_c = max_col - old_c;
        if new_c >= ncell { continue; }
        let mut nc = cell.clone();
        // flip up/down, left/right
        nc.up = cell.down; nc.down = cell.up; nc.left = cell.right; nc.right = cell.left;
        cells[new_c] = nc;
    }
    let mut segs: Vec<(SegKind, Option<usize>)> = vec![(SegKind::Space, None); row.segs.len()];
    for (old_s, seg) in row.segs.iter().enumerate() {
        if max_col == 0 { break; }
        let new_s = max_col - 1 - old_s;
        if new_s >= segs.len() { continue; }
        let kind = match seg.0 { SegKind::ArrowLeft => SegKind::ArrowRight, SegKind::ArrowRight => SegKind::ArrowLeft, other => other };
        segs[new_s] = (kind, seg.1);
    }
    let rev_row = GraphRow { cells, segs, text: row.text.clone() };
    render_single_row(&rev_row, graph, settings)
}

fn render_text(graph: &GitGraph, settings: &Settings) -> String {
    let mut wrapped: Vec<Vec<TextLine>> = Vec::new();
    for i in 0..graph.commits.len() {
        let lines = format_commit_lines(graph, i, &settings.format);
        wrapped.push(wrap_commit_lines(lines, &settings.wrap));
    }
    let renderer = Renderer { graph, settings };
    let rows = renderer.build_rows(&wrapped);
    render_rows_to_string(&rows, graph, settings)
}

// ---------- SVG ----------
fn fmt_num(v: f64) -> String {
    if v == v.trunc() { format!("{}", v as i64) } else { format!("{}", v) }
}
fn xml_escape(s: &str) -> String { s.replace('&', "&amp;").replace('<', "&lt;").replace('>', "&gt;").replace('"', "&quot;") }
fn render_svg(graph: &GitGraph, settings: &Settings) -> String {
    let n = graph.commits.len();
    let width = (graph.max_column as f64 + 2.0) * 15.0;
    let height = (n as f64 + 2.0) * 15.0;
    let mut elems: Vec<String> = Vec::new();
    if settings.debug {
        for b in &graph.branches {
            if let (Some(col), (Some(start), Some(end))) = (b.column, b.range) {
                let x = (col as f64 + 1.0) * 15.0;
                let y1 = (start as f64 + 1.0) * 15.0;
                let y2 = (end as f64 + 1.0) * 15.0;
                elems.push(format!("<line stroke=\"cyan\" stroke-width=\"5\" x1=\"{}\" x2=\"{}\" y1=\"{}\" y2=\"{}\"/>", fmt_num(x), fmt_num(x), fmt_num(y1), fmt_num(y2)));
            }
        }
    }
    // index map by oid
    let pos_of: HashMap<Oid, usize> = graph.commits.iter().enumerate().map(|(i, c)| (c.oid, i)).collect();
    for (i, commit) in graph.commits.iter().enumerate() {
        let bi = commit.branch.unwrap();
        let col = graph.branches[bi].column.unwrap_or(0);
        let x1 = (col as f64 + 1.0) * 15.0;
        let y1 = (i as f64 + 1.0) * 15.0;
        for (pi, poid) in commit.parents.iter().enumerate() {
            let (target_idx, target_col, stroke_branch) = if let Some(&pidx) = pos_of.get(poid) {
                let p_bi = graph.commits[pidx].branch.unwrap();
                let p_col = graph.branches[p_bi].column.unwrap_or(0);
                let s_branch = if pi == 0 { bi } else { p_bi };
                (pidx, p_col, s_branch)
            } else {
                (n, col, bi)
            };
            let x2 = (target_col as f64 + 1.0) * 15.0;
            let y2 = (target_idx as f64 + 1.0) * 15.0;
            let stroke = xml_escape(&graph.branches[stroke_branch].svg_color);
            if target_col == col {
                elems.push(format!("<line stroke=\"{}\" stroke-width=\"1\" x1=\"{}\" x2=\"{}\" y1=\"{}\" y2=\"{}\"/>", stroke, fmt_num(x1), fmt_num(x2), fmt_num(y1), fmt_num(y2)));
            } else {
                let mid_y = y1 + 7.5;
                let mid_x = (x1 + x2) / 2.0;
                let d = format!("M{},{} L{},{} Q{},{} {},{} Q{},{} {},{} L{},{}",
                    fmt_num(x1), fmt_num(y1), fmt_num(x1), fmt_num(y1),
                    fmt_num(x1), fmt_num(mid_y), fmt_num(mid_x), fmt_num(mid_y),
                    fmt_num(x2), fmt_num(mid_y), fmt_num(x2), fmt_num(y1 + 15.0),
                    fmt_num(x2), fmt_num(y2));
                elems.push(format!("<path d=\"{}\" fill=\"none\" stroke=\"{}\" stroke-width=\"1\"/>", d, stroke));
            }
        }
        let stroke = xml_escape(&graph.branches[bi].svg_color);
        let fill = if commit.parents.len() > 1 { "white".to_string() } else { stroke.clone() };
        elems.push(format!("<circle cx=\"{}\" cy=\"{}\" fill=\"{}\" r=\"4\" stroke=\"{}\" stroke-width=\"1\"/>", fmt_num(x1), fmt_num(y1), fill, stroke));
    }
    if elems.is_empty() {
        format!("<svg height=\"{}\" viewBox=\"0 0 {} {}\" width=\"{}\" xmlns=\"http://www.w3.org/2000/svg\"/>\n", fmt_num(height), fmt_num(width), fmt_num(height), fmt_num(width))
    } else {
        let mut out = format!("<svg height=\"{}\" viewBox=\"0 0 {} {}\" width=\"{}\" xmlns=\"http://www.w3.org/2000/svg\">\n", fmt_num(height), fmt_num(width), fmt_num(height), fmt_num(width));
        for e in elems { out.push_str(&e); out.push('\n'); }
        out.push_str("</svg>\n");
        out
    }
}
