        print(" orig rc",a.returncode,"new rc",b.returncode)
        if a.stdout!=b.stdout:
            print("--- orig stdout ---"); print(a.stdout)
            print("--- new stdout ---"); print(b.stdout)
        if a.stderr!=b.stderr:
            # ignore timing lines in debug?
            print("--- orig stderr ---"); print(repr(a.stderr))
            print("--- new stderr ---"); print(repr(b.stderr))
    return ok
