        {
            let mut assigned: std::collections::HashSet<usize> = std::collections::HashSet::new();
            let mut sorted_mvs: Vec<&BoundaryMovement> = movements.iter().collect();
            sorted_mvs.sort_by_key(|mv| std::cmp::Reverse(mv.source.abs_diff(mv.target)));
            for mv in sorted_mvs {
                let lo = mv.source.min(mv.target); let hi = mv.source.max(mv.target);
                for c in lo..=hi {
                    if c == mv.target { continue; }
                    if assigned.contains(&c) { continue; }
                    cells[c].branch = Some(mv.branch);
                    assigned.insert(c);
                }
            }
            // recompute segment colours from chosen endpoint cells
            for s in 0..segs.len() {
                let crossing: Vec<&BoundaryMovement> = movements.iter().filter(|mv| {
                    let lo = mv.source.min(mv.target); let hi = mv.source.max(mv.target);
                    lo <= s && s < hi
                }).collect();
