                let mut kind = SegKind::Horiz;
                for mv in &crossing {
                    if mv.is_start {
                        if mv.target > mv.source && s == mv.source { kind = SegKind::ArrowLeft; }
                        else if mv.target < mv.source && s + 1 == mv.source { kind = SegKind::ArrowRight; }
                    }
                }
                let starts: Vec<&&BoundaryMovement> = crossing.iter().filter(|mv| mv.is_start).collect();
                let branch = if !starts.is_empty() {
                    let mv = starts.iter().min_by_key(|mv| {
                        if mv.target > s { mv.target - (s + 1) } else { s.saturating_sub(mv.target) }
                    }).unwrap();
                    cells[mv.target].branch.or(Some(mv.target_branch))
                } else {
                    let mv = crossing.iter().min_by_key(|mv| {
                        if mv.source > s { mv.source - (s + 1) } else { s.saturating_sub(mv.source) }
                    }).unwrap();
                    cells[mv.source].branch.or(Some(mv.branch))
                };
                segs[s] = (kind, branch);
            }
        }
        GraphRow { cells, segs, text: vec![frag("", None)] }
    }"""
