import random, os, shutil

def gen(path, seed):
    rng=random.Random(seed)
    if os.path.exists(path): shutil.rmtree(path)
    os.makedirs(path)
    sh("git init -q -b master", path)
    day=[1]
    def nextdate():
        day[0]+=1
        return f"2020-02-{day[0]:02d}T10:00:00+00:00" if day[0]<=28 else f"2020-03-{day[0]-28:02d}T10:00:00+00:00"
    def commit(msg):
        cf(path, f"f{day[0]}_{rng.randint(0,100000)}.txt", nextdate(), msg)
    commit("root")
    branches=["master"]
    active="master"
    nbranch=0
    for step in range(rng.randint(5,14)):
        action=rng.choice(["commit","branch","merge","commit","branch","merge","tag","checkout"])
        if action=="branch":
            nbranch+=1
            name=rng.choice(["feature","release","hotfix","dev-","topic-"])+str(nbranch) if rng.random()<0.5 else rng.choice(["feature/x","develop","feature/y","hotfix/z"])+ (str(nbranch) if rng.random()<0.3 else "")
            # ensure unique
            name=name+ "_" + str(step) if rng.random()<0.4 else name
            if name in branches: continue
            sh(f"git checkout -q -b {name}", path)
            branches.append(name); active=name
            commit(f"commit-on-{name}")
        elif action=="merge":
            others=[b for b in branches if b!=active]
            if not others: continue
            other=rng.choice(others)
            try:
                sh(f"git merge -q --no-ff {other} -m merge-{other}-into-{active}", path, nextdate())
            except SystemExit:
                pass
            if rng.random()<0.4:
                try: sh(f"git branch -q -D {other}", path); branches.remove(other)
                except SystemExit: pass
        elif action=="tag":
            sh(f"git tag v{step}", path)
        elif action=="checkout":
            active=rng.choice(branches)
            sh(f"git checkout -q {active}", path)
        else:
            commit(f"commit-{step}")
    sh("git checkout -q master", path)
    return path

if __name__=="__main__":
    for seed in range(int(sys.argv[1]), int(sys.argv[2])):
        gen(f"/tmp/rand{seed}", seed)
        print("generated", seed)
