def run(exe,args,home,cwd="/tmp/branch1"):
 env=os.environ.copy(); env["HOME"]=home; env.pop("XDG_CONFIG_HOME",None)
 return subprocess.run([exe]+args,cwd=cwd,capture_output=True,text=True,env=env)
home="/tmp/empty_models_home"
if os.path.exists(home): shutil.rmtree(home)
os.makedirs(home+"/.config/git-graph/models")
for args in [["model","--list"],["model","simple"],["--model","simple"],["model"]]:
 for exe in ["/workspace/executable","/tmp/newbin/executable"]:
  r=run(exe,args,home); print(exe,args,r.returncode,repr(r.stdout),repr(r.stderr))
PY"}

